    n, m = map(int, sys.stdin.readline().split())
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    documents = []
    signed_by = {}

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    for _ in range(m):
        event = sys.stdin.readline().split()
        t = int(event[0])
        if t == 1:
            x, y = int(event[1]), int(event[2])
            union(x, y)
        elif t == 2:
            x = int(event[1])
            root = find(x)
            documents.append(root)
            if root not in signed_by:
                signed_by[root] = set()
            signed_by[root].add(len(documents))
        elif t == 3:
            x, i = int(event[1]), int(event[2])
            root = find(x)
            if root in signed_by and i in signed_by[root]:
                print("YES")
            else:
                print("NO")

